import assert from "node:assert/strict";
import { TrustedRefreshAdmissionRegistry as Previous } from "../base/qa/openbao-acceptance/authbus/authbus_refresh_registry_candidate.mjs";
import { TrustedRefreshAdmissionRegistry as Candidate } from "../work/qa/openbao-acceptance/authbus/authbus_refresh_registry_candidate.mjs";
import { digest } from "../work/qa/openbao-acceptance/authbus/authbus_admission_authority_candidate.mjs";

// A unit fixture for the exact scope gate. No SDK, provider, filesystem,
// trusted control source or durable refresh completion is simulated as passed.
const scope = { hostId: "unit", agentId: "unit", agentDir: "/tmp/authbus-successor-unit", provider: "anthropic" };
const profileId = "anthropic:unit";
const oldCredential = { type: "oauth", provider: "anthropic", access: "unit-old-access", refresh: "unit-old-refresh", expires: 1 };
const newCredential = { ...oldCredential, access: "unit-new-access", refresh: "unit-new-refresh", expires: 9000000000000 };
const oldPermit = { allowed: true, epoch: 1, leaseId: "old", profileId, credentialDigest: digest(oldCredential) };
const currentPermit = { ...oldPermit, epoch: 3, leaseId: "current", credentialDigest: digest(newCredential) };
const authority = { scope, inspect: () => ({ ...currentPermit }) };
const create = Type => new Type({ authorities: [authority], resolveDefaultAgentDir: () => scope.agentDir,
  resolveProviderIdForAuth: provider => typeof provider === "string" ? provider : "",
  readStore: () => ({ profiles: { [profileId]: newCredential } }),
  refreshBindings: [{ scope, controlSource: {}, coordinator: {}, commitCredential: () => true }] });
const params = { agentDir: scope.agentDir, credential: oldCredential };
const previous = create(Previous), candidate = create(Candidate);
const checks = [];
function check(name, operation) { operation(); checks.push(name); }
const rejected = operation => assert.throws(operation, error => typeof error.diagnosticCode === "string");
check("previous_credential_only_scope_bypass_reproduced", () =>
  assert.equal(previous.advanceAfterRefresh(params, oldPermit, profileId, oldCredential.access), oldPermit));
check("candidate_credential_only_old_wire_rejected", () =>
  rejected(() => candidate.advanceAfterRefresh(params, oldPermit, profileId, oldCredential.access)));
check("candidate_missing_scope_rejected", () =>
  rejected(() => candidate.advanceAfterRefresh({ agentDir: scope.agentDir }, oldPermit, profileId, newCredential.access)));
check("candidate_claimed_unmanaged_scope_rejected", () =>
  rejected(() => candidate.advanceAfterRefresh({ ...params, provider: "unmanaged" }, oldPermit, profileId, newCredential.access)));
check("candidate_provider_auth_key_cannot_skip_epoch_gate", () =>
  rejected(() => candidate.advanceAfterRefresh({ agentDir: scope.agentDir, providerAuthKey: "anthropic" }, oldPermit, profileId, oldCredential.access)));
check("candidate_old_wire_auth_result_rejected", () =>
  rejected(() => candidate.bindCredentialResult(params, oldPermit, profileId, { apiKey: oldCredential.access }, oldCredential.access)));
check("candidate_current_owned_permit_still_accepted", () =>
  assert.equal(candidate.advanceAfterRefresh(params, currentPermit, profileId, newCredential.access), currentPermit));
process.stdout.write(JSON.stringify({ schema: "authbus-refresh-successor-scope-unit-regression", actualSdkExecution: false,
  actualNativeHeptaBao: false, actualProvider: false, checksPassed: checks.length, checks }, null, 2) + "\n");
